problems.solutionCode:
using System;
using System.Numerics;

public static class Vision
{
    public static bool IsInSight(Vector3 observerPos, Vector3 observerForward,
                                 Vector3 targetPos, float fovDegrees, float viewDistance)
    {
        // 1) 잘못된 입력: 방향이 없는 forward, 음수(또는 NaN) 거리, 0 이하의 시야각
        float forwardLenSq = observerForward.LengthSquared();
        if (forwardLenSq == 0f || !(viewDistance >= 0f) || !(fovDegrees > 0f)) return false;

        // 2) 거리: 제곱끼리 비교해 Sqrt 를 피한다 (경계 포함)
        Vector3 toTarget = targetPos - observerPos;
        float distSq = toTarget.LengthSquared();
        if (distSq > viewDistance * viewDistance) return false;

        // 3) 같은 위치: 방향을 정의할 수 없으므로 "보인다"로 약속한다
        if (distSq == 0f) return true;
        if (fovDegrees >= 360f) return true;

        // 4) 각도: cos(theta) = dot / (|f||d|) >= cos(fov/2)
        //    양변에 |f||d| (> 0) 를 곱하면 dot >= cosHalf * |f| * |d|.
        //    제곱해서 Sqrt 를 없애되, 제곱은 부호를 지우므로 부호별로 나눠 비교한다.
        float cosHalf = MathF.Cos(fovDegrees * 0.5f * (MathF.PI / 180f)); // MathF 는 라디안
        float dot = Vector3.Dot(observerForward, toTarget);
        float rhsSq = cosHalf * cosHalf * forwardLenSq * distSq;

        if (cosHalf >= 0f)                      // 시야각 180도 이하: 앞쪽 반공간 안에서만 보인다
            return dot >= 0f && dot * dot >= rhsSq;
        return dot >= 0f || dot * dot <= rhsSq; // 180도 초과: 뒤쪽 일부까지 보인다
    }
}

