public static class __Judge
{
    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.Numerics.Vector3 V(float x, float y, float z) { return new System.Numerics.Vector3(x, y, z); }

    // forward = +Z 기준으로 수평 또는 수직 방향으로 deg 만큼 벗어난, 거리 dist 의 점
    static System.Numerics.Vector3 At(double deg, float dist, bool vertical)
    {
        double r = deg * System.Math.PI / 180.0;
        float s = (float)(System.Math.Sin(r) * dist), c = (float)(System.Math.Cos(r) * dist);
        return vertical ? V(0f, s, c) : V(s, 0f, c);
    }

    static string Check(string what, System.Numerics.Vector3 pos, System.Numerics.Vector3 fwd, System.Numerics.Vector3 target, float fov, float dist, bool expected)
    {
        bool got = Vision.IsInSight(pos, fwd, target, fov, dist);
        if (got == expected) return null;
        return what + ": 관찰자 " + pos + ", forward " + fwd + ", 타깃 " + target + ", fov " + fov + ", 시야 거리 " + dist + " → 기대 " + expected + " / 결과 " + got;
