            ?? Check("fov 270 에서 정면", O, F, V(0f, 0f, 5f), 270f, 10f, true)
            ?? Check("fov 360 에서 정반대", O, F, V(0f, 0f, -5f), 360f, 10f, true)
            ?? Check("fov 360 이어도 거리 밖", O, F, V(0f, 0f, -11f), 360f, 10f, false)
            ?? Check("fov 400 (360 이상은 거리만 검사) 에서 정반대", O, F, V(0f, 0f, -5f), 400f, 10f, true));

        Run("invalid-input", () =>
            Check("forward 가 영벡터", O, V(0f, 0f, 0f), V(0f, 0f, 5f), 90f, 10f, false)
            ?? Check("음수 시야 거리", O, F, V(0f, 0f, 5f), 90f, -1f, false)
            ?? Check("시야각 0 (정면이어도 false)", O, F, V(0f, 0f, 5f), 0f, 10f, false)
            ?? Check("음수 시야각", O, F, V(0f, 0f, 5f), -90f, 10f, false));

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            int tested = 0;
            for (int i = 0; i < 4000; i++)
            {
                var pos = V((float)(rng.NextDouble() * 40 - 20), (float)(rng.NextDouble() * 10 - 5), (float)(rng.NextDouble() * 40 - 20));
                var fwd = V((float)(rng.NextDouble() * 2 - 1), (float)(rng.NextDouble() * 2 - 1), (float)(rng.NextDouble() * 2 - 1));
                if (fwd.Length() < 0.2f) continue;
                fwd *= (float)(0.1 + rng.NextDouble() * 20);
                var target = pos + V((float)(rng.NextDouble() * 30 - 15), (float)(rng.NextDouble() * 30 - 15), (float)(rng.NextDouble() * 30 - 15));
                float fov = (float)(10 + rng.NextDouble() * 340);
                float view = 12f;
                // 기준 구현: double + Acos 로 각도를 직접 구한다
                double dx = (double)target.X - pos.X, dy = (double)target.Y - pos.Y, dz = (double)target.Z - pos.Z;
                double d = System.Math.Sqrt(dx * dx + dy * dy + dz * dz);
                double fl = System.Math.Sqrt((double)fwd.X * fwd.X + (double)fwd.Y * fwd.Y + (double)fwd.Z * fwd.Z);
                if (d < 0.05) continue;
                double cos = (dx * fwd.X + dy * fwd.Y + dz * fwd.Z) / (d * fl);
                double ang = System.Math.Acos(System.Math.Max(-1.0, System.Math.Min(1.0, cos))) * 180.0 / System.Math.PI;
                // 경계 근처(각도 0.5도, 거리 0.01 이내)는 부동소수 오차 때문에 판정하지 않는다
                if (System.Math.Abs(ang - fov * 0.5) < 0.5 || System.Math.Abs(d - view) < 0.01) continue;
                bool expected = d <= view && ang <= fov * 0.5;
                tested++;
                string e = Check("무작위 #" + i + " (각도 " + ang.ToString("F1") + "도, 거리 " + d.ToString("F2") + ")", pos, fwd, target, fov, view, expected);
                if (e != null) return e;
            }
            return tested > 3000 ? null : "검사한 표본 수가 부족함: " + tested;
        });
    }
}

