using System;
using System.Numerics;

public static class FrameMath
{
    private static float Lerp(float a, float b, float t) => a + (b - a) * t;

    // 매 프레임 호출: current 가 target 을 부드럽게 따라간다 (카메라, HP 바).
    // sharpness : 따라가는 빠르기(1/초). dt : 이번 프레임의 경과 시간(초).
    public static float SmoothFollow(float current, float target, float sharpness, float dt)
    {
        return Lerp(current, target, 0.1f);
    }

    // 매 프레임 호출: 등가속도 운동(점프, 투사체)을 dt 만큼 진행시킨다.
    public static void Integrate(ref Vector2 position, ref Vector2 velocity, Vector2 acceleration, float dt)
    {
        velocity += acceleration * dt;
        position += velocity;
    }
}

