using System;
using System.Numerics;

// 축 정렬 경계 상자. Min.X <= Max.X, Min.Y <= Max.Y 라고 가정한다.
public readonly struct Aabb
{
    public readonly Vector2 Min;
    public readonly Vector2 Max;
    public Aabb(Vector2 min, Vector2 max) { Min = min; Max = max; }
}

public static class Collision2D
{
    // 분리축: X 구간과 Y 구간이 "둘 다" 겹쳐야 상자가 겹친다.
    // 맞닿음은 충돌이 아니라고 약속했으므로 엄격한 부등호(<)를 쓴다.
    public static bool AabbOverlap(Aabb a, Aabb b)
    {
        return a.Min.X < b.Max.X && b.Min.X < a.Max.X
            && a.Min.Y < b.Max.Y && b.Min.Y < a.Max.Y;
    }

    // 축마다 독립적으로 [Min, Max] 구간에 클램프한다.
    public static Vector2 ClosestPoint(Aabb box, Vector2 p)
    {
        return new Vector2(Math.Clamp(p.X, box.Min.X, box.Max.X),
                           Math.Clamp(p.Y, box.Min.Y, box.Max.Y));
    }

    // 원의 중심에서 상자 위 가장 가까운 점까지의 제곱 거리를 반지름 제곱과 비교한다.
    // 중심이 상자 안이면 가장 가까운 점이 중심 자신이라 거리 0 → 겹침.
    public static bool CircleAabbOverlap(Vector2 center, float radius, Aabb box)
    {
        if (!(radius > 0f)) return false;
        Vector2 d = center - ClosestPoint(box, center);
        return d.LengthSquared() < radius * radius; // 맞닿음(==)은 제외
    }
}

