        Run("circle-corner", () =>
            Circle("꼭짓점 대각선 방향: 원의 외접 사각형은 겹치지만 원은 안 겹침", 5f, 5f, 1.2f, box, false)
            ?? Circle("같은 위치, 반지름 1.5 (대각선 거리 1.414)", 5f, 5f, 1.5f, box, true)
            ?? Circle("왼쪽 아래 꼭짓점 방향", -1f, -1f, 1.2f, box, false)
            ?? Circle("꼭짓점까지 3-4-5, 반지름 5.01", 7f, 8f, 5.01f, box, true)
            ?? Circle("꼭짓점까지 3-4-5, 반지름 4.99", 7f, 8f, 4.99f, box, false));

        Run("circle-touching", () =>
            Circle("변에 정확히 닿음 (거리 2, 반지름 2)", 6f, 2f, 2f, box, false)
            ?? Circle("변을 0.001 파고듦", 6f, 2f, 2.001f, box, true)
            ?? Circle("꼭짓점에 정확히 닿음 (3-4-5)", 7f, 8f, 5f, box, false)
            ?? Circle("위쪽 변에 정확히 닿음", 2f, 4.5f, 0.5f, box, false)
            ?? Circle("반지름 0, 중심이 상자 안", 2f, 2f, 0f, box, false)
            ?? Circle("음수 반지름", 2f, 2f, -1f, box, false));

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            for (int i = 0; i < 4000; i++)
            {
                // 정수 좌표: 맞닿는 경우가 자주 나오고 오차가 없다
                int ax = rng.Next(-8, 8), ay = rng.Next(-8, 8), bx = rng.Next(-8, 8), by = rng.Next(-8, 8);
                var a = B(ax, ay, ax + rng.Next(1, 6), ay + rng.Next(1, 6));
                var b = B(bx, by, bx + rng.Next(1, 6), by + rng.Next(1, 6));
                // 기준 구현: 어느 한 축에서라도 떨어져(또는 맞닿아) 있으면 겹치지 않는다
                bool sep = a.Max.X <= b.Min.X || b.Max.X <= a.Min.X || a.Max.Y <= b.Min.Y || b.Max.Y <= a.Min.Y;
                string e = Box("무작위 #" + i, a, b, !sep);
                if (e != null) return e;

                float cx = (float)(rng.NextDouble() * 24 - 12), cy = (float)(rng.NextDouble() * 24 - 12), r = (float)(0.1 + rng.NextDouble() * 5);
                // 기준 구현: 축별로 상자 밖으로 벗어난 양(음수면 0)으로 거리를 구한다
                double ox = System.Math.Max(System.Math.Max((double)a.Min.X - cx, (double)cx - a.Max.X), 0.0);
                double oy = System.Math.Max(System.Math.Max((double)a.Min.Y - cy, (double)cy - a.Max.Y), 0.0);
                double dist = System.Math.Sqrt(ox * ox + oy * oy);
                if (System.Math.Abs(dist - r) < 0.001) continue; // 맞닿는 경계 근처는 제외
                e = Circle("무작위 #" + i + " (가장 가까운 점까지 거리 " + dist.ToString("F3") + ")", cx, cy, r, a, dist < r);
                if (e != null) return e;
            }
            return null;
        });
    }
}

