public static class __Judge
{
    const float Eps = 0.001f; // 거리 비교 허용 오차

    static void Run(string id, System.Func<string> body)
    {
        string err;
        try { err = body(); }
        catch (System.Exception e) { err = "예외 발생: " + e.GetType().Name; }
        System.Console.WriteLine(err == null ? "[PASS] " + id : "[FAIL] " + id + " :: " + err);
    }

    static System.Numerics.Vector3 V(float x, float y, float z) { return new System.Numerics.Vector3(x, y, z); }

    static string Desc(System.Numerics.Vector3 o, System.Numerics.Vector3 d, System.Numerics.Vector3 c, float r)
    {
        return "origin " + o + ", direction " + d + ", 구 중심 " + c + " 반지름 " + r;
    }

    static string Hit(string what, System.Numerics.Vector3 o, System.Numerics.Vector3 d, System.Numerics.Vector3 c, float r, float expected, float eps)
    {
        float dist;
        bool hit = Hitscan.RaySphere(o, d, c, r, out dist);
        if (!hit) return what + ": " + Desc(o, d, c, r) + " → 기대 명중(거리 " + expected + ") / 결과 빗나감";
        if (!(System.Math.Abs(dist - expected) <= eps)) return what + ": " + Desc(o, d, c, r) + " → 거리 기대 " + expected + " / 결과 " + dist;
        return null;
    }

    static string Miss(string what, System.Numerics.Vector3 o, System.Numerics.Vector3 d, System.Numerics.Vector3 c, float r)
    {
        float dist;
        bool hit = Hitscan.RaySphere(o, d, c, r, out dist);
        return hit ? what + ": " + Desc(o, d, c, r) + " → 기대 빗나감 / 결과 명중(거리 " + dist + ")" : null;
    }

    public static void Main()
    {
        var Z = V(0f, 0f, 1f);
        var C0 = V(0f, 0f, 0f);

        Run("head-on-nearest-hit", () =>
            Hit("정면 명중: 들어가는 점(8)이지 나가는 점(12)이 아님", V(0f, 0f, -10f), Z, C0, 2f, 8f, Eps)
            ?? Hit("중심에서 벗어난 명중 (3-4-5)", V(3f, 0f, -10f), Z, C0, 5f, 6f, Eps)
            ?? Hit("원점이 아닌 구", V(1f, 2f, 3f), V(1f, 0f, 0f), V(11f, 2f, 3f), 1.5f, 8.5f, Eps)
            ?? Hit("대각선 방향", V(-10f, -10f, 0f), V(0.70710678f, 0.70710678f, 0f), C0, 1f, 13.142136f, Eps));

        Run("miss", () =>
            Miss("옆으로 빗나감", V(3f, 0f, -10f), Z, C0, 2f)
            ?? Miss("아슬아슬하게 빗나감", V(0f, 2.01f, -10f), Z, C0, 2f)
            ?? Miss("방향이 구와 수직", V(0f, 0f, -10f), V(1f, 0f, 0f), C0, 2f));

        Run("pointing-away", () =>
            Miss("구가 정확히 뒤에 있음", V(0f, 0f, -10f), V(0f, 0f, -1f), C0, 2f)
            ?? Miss("구가 비스듬히 뒤에 있음", V(0f, 0f, 10f), V(0.1f, 0f, 1f), C0, 3f)
            ?? Miss("구를 이미 지나친 뒤", V(0f, 0f, 2.5f), Z, C0, 2f));

        Run("origin-inside", () =>
            Hit("중심에서 발사", C0, Z, C0, 2f, 0f, Eps)
            ?? Hit("구 안에서 중심 쪽으로", V(0f, 1f, -1f), Z, C0, 2f, 0f, Eps)
            ?? Hit("구 안에서 바깥쪽으로", V(0f, 0f, 1.5f), Z, C0, 2f, 0f, Eps)
            ?? Hit("큰 구 안, 정규화되지 않은 방향", V(40f, -30f, 10f), V(-3f, 2f, 9f), V(35f, -28f, 12f), 50f, 0f, Eps));

        Run("tangent", () =>
            Hit("접선 (판별식 0)", V(0f, 1f, -5f), Z, C0, 1f, 5f, Eps)
            ?? Hit("접선, 길이 2 인 방향", V(0f, 1f, -5f), V(0f, 0f, 2f), C0, 1f, 5f, Eps)
            ?? Hit("접선, -X 쪽에서", V(-8f, -3f, 0f), V(1f, 0f, 0f), C0, 3f, 8f, Eps));

        Run("non-normalized-direction", () =>
            Hit("길이 5 인 방향: 거리는 8 (t = 1.6 이 아님)", V(0f, 0f, -10f), V(0f, 0f, 5f), C0, 2f, 8f, Eps)
            ?? Hit("길이 0.01 인 방향", V(0f, 0f, -10f), V(0f, 0f, 0.01f), C0, 2f, 8f, Eps)
            ?? Hit("방향 (3,0,4)", V(-6f, 0f, -8f), V(3f, 0f, 4f), C0, 1f, 9f, Eps)
            ?? Miss("길이 5 인 방향으로 빗나감", V(3f, 0f, -10f), V(0f, 0f, 5f), C0, 2f)
            ?? Miss("길이 5 인 방향, 구가 뒤", V(0f, 0f, -10f), V(0f, 0f, -5f), C0, 2f));

        Run("zero-direction", () =>
        {
            string e = Miss("direction 이 영벡터", V(0f, 0f, -10f), V(0f, 0f, 0f), C0, 2f)
                ?? Miss("음수 반지름", V(0f, 0f, -10f), Z, C0, -1f);
            if (e != null) return e;
            float dist;
            bool hit = Hitscan.RaySphere(V(0f, 0f, -10f), V(0f, 0f, 0f), C0, 2f, out dist);
            return float.IsNaN(dist) ? "영벡터 방향에서 distance 가 NaN" : null;
        });

        Run("random-vs-reference", () =>
        {
            var rng = new System.Random(20261122);
            int hits = 0, tested = 0;
            for (int i = 0; i < 4000; i++)
            {
                var o = V((float)(rng.NextDouble() * 40 - 20), (float)(rng.NextDouble() * 40 - 20), (float)(rng.NextDouble() * 40 - 20));
                var c = V((float)(rng.NextDouble() * 20 - 10), (float)(rng.NextDouble() * 20 - 10), (float)(rng.NextDouble() * 20 - 10));
                float r = (float)(0.5 + rng.NextDouble() * 8);
                // 절반은 구 근처를 겨냥해 명중이 충분히 나오게 한다
                var aim = c + V((float)(rng.NextDouble() * 2 - 1), (float)(rng.NextDouble() * 2 - 1), (float)(rng.NextDouble() * 2 - 1)) * (r * 1.3f);
                var d = i % 2 == 0 ? aim - o : V((float)(rng.NextDouble() * 2 - 1), (float)(rng.NextDouble() * 2 - 1), (float)(rng.NextDouble() * 2 - 1));
                if (d.Length() < 0.1f) continue;
                d *= (float)(0.05 + rng.NextDouble() * 4) / d.Length();
                // 기준 구현(double, 기하학적 방법): 중심을 반직선에 투영해 가장 가까운 접근 거리를 구한다
                double lx = (double)c.X - o.X, ly = (double)c.Y - o.Y, lz = (double)c.Z - o.Z;
                double dl = System.Math.Sqrt((double)d.X * d.X + (double)d.Y * d.Y + (double)d.Z * d.Z);
                double ux = d.X / dl, uy = d.Y / dl, uz = d.Z / dl;
                double l2 = lx * lx + ly * ly + lz * lz, L = System.Math.Sqrt(l2);
                double tca = lx * ux + ly * uy + lz * uz;
                double perp = System.Math.Sqrt(System.Math.Max(0.0, l2 - tca * tca));
                // 구 표면 근처에서 출발하거나 접선에 가까운 경우는 오차 때문에 판정하지 않는다
                if (System.Math.Abs(L - r) < 0.01 || System.Math.Abs(perp - r) < 0.01) continue;
                tested++;
                string e;
                if (L < r) e = Hit("무작위 #" + i + " (구 안에서 출발)", o, d, c, r, 0f, Eps);
                else if (tca < 0 || perp > r) e = Miss("무작위 #" + i, o, d, c, r);
                else { hits++; e = Hit("무작위 #" + i, o, d, c, r, (float)(tca - System.Math.Sqrt((double)r * r - perp * perp)), 0.005f); }
                if (e != null) return e;
            }
            return tested > 3000 && hits > 500 ? null : "검사한 표본 수가 부족함: " + tested + " / 명중 " + hits;
        });
    }
}
